"""INFO tab — displays per-session usage, cost, and quota data.

Reads session-tracker JSON files on a timer and displays a table
with one row per session plus an aggregate summary.
"""

import logging
import tkinter as tk
from datetime import date, datetime, timezone
from tkinter import ttk

from personal_assistant_dashboard.config import (
    BG_WINDOW,
    COLOR_ERROR,
    COLOR_SUCCESS,
    COLOR_WARNING,
    FG_DIM,
    FG_TEXT,
    FONT_NAME_BODY,
    FONT_NAME_HEADING,
    PAD,
)
from personal_assistant_dashboard.models import ConsoleLogCallback
from personal_assistant_dashboard.session_tracker import (
    AggregateData,
    SessionData,
    aggregate,
    format_cost,
    format_duration_compact,
    format_tokens,
    load_sessions,
)

logger = logging.getLogger(__name__)

REFRESH_INTERVAL_MS = 30_000

# Treeview column definitions: (id, heading, width, anchor)
_COLUMNS = [
    ("project", "Project", 120, tk.W),
    ("model", "Model", 60, tk.W),
    ("cost", "Cost", 60, tk.E),
    ("tok_in", "Tok In", 60, tk.E),
    ("tok_out", "Tok Out", 60, tk.E),
    ("ctx_pct", "Ctx %", 50, tk.E),
    ("five_h", "5h %", 50, tk.E),
    ("seven_d", "7d %", 50, tk.E),
    ("duration", "Dur", 50, tk.E),
    ("lines", "Lines", 70, tk.E),
]

# Percentage thresholds for color coding
_THRESHOLD_MID = 60
_THRESHOLD_HIGH = 90


class InfoTab:
    """INFO tab displaying session usage data in a table."""

    def __init__(
        self,
        parent: tk.Frame,
        root: tk.Tk,
        *,
        console_log: ConsoleLogCallback | None = None,
        cwd_filter: str | None = None,
    ) -> None:
        self._parent = parent
        self._root = root
        self._console_log = console_log
        self._cwd_filter = cwd_filter
        self._refresh_timer: str | None = None

        self._build()
        self._schedule_refresh()

    def _build(self) -> None:
        """Build the tab UI."""
        # Aggregate summary at top
        self._summary_label = tk.Label(
            self._parent,
            text="Loading...",
            bg=BG_WINDOW,
            fg=FG_TEXT,
            font=FONT_NAME_HEADING,
            anchor=tk.W,
            padx=PAD,
            pady=PAD,
        )
        self._summary_label.pack(fill=tk.X)

        # Treeview table
        col_ids = [c[0] for c in _COLUMNS]
        style = ttk.Style()
        style.configure(
            "Info.Treeview",
            background=BG_WINDOW,
            foreground=FG_TEXT,
            fieldbackground=BG_WINDOW,
            borderwidth=0,
            rowheight=22,
        )
        style.configure(
            "Info.Treeview.Heading",
            background="#333333",
            foreground=FG_TEXT,
            borderwidth=0,
        )
        style.map(
            "Info.Treeview",
            background=[("selected", "#444444")],
            foreground=[("selected", FG_TEXT)],
        )

        self._tree = ttk.Treeview(
            self._parent,
            columns=col_ids,
            show="headings",
            style="Info.Treeview",
            selectmode="none",
        )
        for col_id, heading, width, anchor in _COLUMNS:
            self._tree.heading(col_id, text=heading)
            self._tree.column(  # type: ignore[call-overload]
                col_id, width=width, anchor=anchor, minwidth=40
            )

        # Tag-based colors for percentage cells
        self._tree.tag_configure("pct_ok", foreground=COLOR_SUCCESS)
        self._tree.tag_configure("pct_mid", foreground=COLOR_WARNING)
        self._tree.tag_configure("pct_high", foreground=COLOR_ERROR)
        self._tree.tag_configure("aggregate", foreground=FG_TEXT)

        scrollbar = tk.Scrollbar(
            self._parent, orient=tk.VERTICAL, command=self._tree.yview
        )
        self._tree.configure(yscrollcommand=scrollbar.set)
        self._tree.pack(fill=tk.BOTH, expand=True, padx=PAD)
        scrollbar.pack(side=tk.RIGHT, fill=tk.Y)

        # Bottom bar: last-updated + refresh button
        bottom = tk.Frame(self._parent, bg=BG_WINDOW)
        bottom.pack(fill=tk.X, padx=PAD, pady=(0, PAD))

        self._status_label = tk.Label(
            bottom,
            text="",
            bg=BG_WINDOW,
            fg=FG_DIM,
            font=FONT_NAME_BODY,
            anchor=tk.W,
        )
        self._status_label.pack(side=tk.LEFT)

        refresh_btn = tk.Button(
            bottom,
            text="\u21bb",  # ↻
            bg=BG_WINDOW,
            fg=FG_TEXT,
            font=FONT_NAME_BODY,
            borderwidth=0,
            command=self._manual_refresh,
            cursor="hand2",
        )
        refresh_btn.pack(side=tk.RIGHT)

    def _schedule_refresh(self) -> None:
        """Schedule the next auto-refresh."""
        self._refresh()
        self._refresh_timer = self._root.after(
            REFRESH_INTERVAL_MS, self._schedule_refresh
        )

    def _manual_refresh(self) -> None:
        """Handle manual refresh button click."""
        if self._refresh_timer:
            self._root.after_cancel(self._refresh_timer)
        self._schedule_refresh()

    def _refresh(self) -> None:
        """Reload session data and update the display."""
        sessions = load_sessions(date.today(), cwd_filter=self._cwd_filter)
        agg = aggregate(sessions)
        self._update_summary(agg)
        self._update_table(sessions, agg)
        now = datetime.now(timezone.utc).strftime("%H:%M:%S")
        self._status_label.configure(
            text=f"Last updated: {now}  \u2022  {agg.session_count} session(s)"
        )

    def _update_summary(self, agg: AggregateData) -> None:
        """Update the aggregate summary label."""
        if agg.session_count == 0:
            self._summary_label.configure(text="No sessions found today")
            return

        parts = [
            format_cost(agg.total_cost_usd),
            f"{format_tokens(agg.total_input_tokens)} in / "
            f"{format_tokens(agg.total_output_tokens)} out",
            f"5h: {agg.max_five_hour_pct}%",
            f"7d: {agg.max_seven_day_pct}%",
        ]
        self._summary_label.configure(text="  \u2022  ".join(parts))

        # Color the summary based on worst rate limit
        worst = max(agg.max_five_hour_pct, agg.max_seven_day_pct)
        self._summary_label.configure(fg=_pct_color(worst))

    def _update_table(self, sessions: list[SessionData], agg: AggregateData) -> None:
        """Rebuild the treeview rows."""
        self._tree.delete(*self._tree.get_children())

        if not sessions:
            return

        # Aggregate row first
        self._tree.insert(
            "",
            tk.END,
            values=(
                "",
                f"TOTAL ({agg.session_count})",
                format_cost(agg.total_cost_usd),
                format_tokens(agg.total_input_tokens),
                format_tokens(agg.total_output_tokens),
                "",
                f"{agg.max_five_hour_pct}%",
                f"{agg.max_seven_day_pct}%",
                "",
                f"+{agg.total_lines_added}/-{agg.total_lines_removed}",
            ),
            tags=("aggregate",),
        )

        # Individual sessions
        for s in sessions:
            # Short model name: extract first word of display name
            model_short = (
                s.model_display_name.split()[0]
                if s.model_display_name != "unknown"
                else "?"
            )
            worst_pct = max(s.five_hour_pct, s.seven_day_pct, s.context_used_pct)
            tag = _pct_tag(worst_pct)

            self._tree.insert(
                "",
                tk.END,
                values=(
                    _project_name(s.cwd),
                    model_short,
                    format_cost(s.total_cost_usd),
                    format_tokens(s.total_input_tokens),
                    format_tokens(s.total_output_tokens),
                    f"{s.context_used_pct}%",
                    f"{s.five_hour_pct}%",
                    f"{s.seven_day_pct}%",
                    format_duration_compact(s.total_duration_ms),
                    f"+{s.lines_added}/-{s.lines_removed}",
                ),
                tags=(tag,),
            )

    def destroy(self) -> None:
        """Cancel timers on cleanup."""
        if self._refresh_timer:
            self._root.after_cancel(self._refresh_timer)
            self._refresh_timer = None


def _project_name(cwd: str) -> str:
    """Extract a short project name from a cwd path.

    For worktree paths like '.../git-worktrees/I45-info-tab', returns the
    worktree name. Otherwise returns the last path component.
    """
    from pathlib import PurePosixPath

    # Normalize to forward slashes for consistent parsing
    normalized = cwd.replace("\\", "/")
    parts = PurePosixPath(normalized).parts

    # If path contains git-worktrees, use the worktree name
    if "git-worktrees" in parts:
        idx = parts.index("git-worktrees")
        if idx + 1 < len(parts):
            return parts[idx + 1]

    # Otherwise use the last component
    return parts[-1] if parts else "?"


def _pct_color(pct: int) -> str:
    """Return a color string for a percentage value."""
    if pct >= _THRESHOLD_HIGH:
        return COLOR_ERROR
    if pct >= _THRESHOLD_MID:
        return COLOR_WARNING
    return COLOR_SUCCESS


def _pct_tag(pct: int) -> str:
    """Return a treeview tag name for a percentage value."""
    if pct >= _THRESHOLD_HIGH:
        return "pct_high"
    if pct >= _THRESHOLD_MID:
        return "pct_mid"
    return "pct_ok"
